//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns `true` for transient errors, which the retry policy may retry;
    /// permanent errors return `false` and abort the run immediately.
    pub fn is_transient(&self) -> bool {
        matches!(self, RetryError::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn transient_errors_are_retryable() {
        assert!(RetryError::Transient("blip".into()).is_transient());
    }

    #[test]
    fn permanent_errors_are_not_retryable() {
        assert!(!RetryError::Permanent("bad input".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Upper bound for every retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay (ms) before the retry with the given 0-based index,
    /// where `0` is the first retry (after the first failed attempt).
    ///
    /// The delay follows exponential growth `base_delay_ms * 2^index`,
    /// computed with saturating arithmetic so it never overflows, and is
    /// capped at `max_delay_ms`.
    pub fn retry_delay_ms(&self, retry_index: u32) -> u64 {
        let doubled = if retry_index >= 63 {
            u64::MAX
        } else {
            self.base_delay_ms.saturating_mul(1u64 << retry_index)
        };
        doubled.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    fn config(base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts: 5,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn first_retry_uses_base_delay() {
        assert_eq!(config(10, 1000).retry_delay_ms(0), 10);
    }

    #[test]
    fn delay_grows_exponentially() {
        let cfg = config(10, 1000);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(1), 20);
        assert_eq!(cfg.retry_delay_ms(2), 40);
        assert_eq!(cfg.retry_delay_ms(3), 80);
        assert_eq!(cfg.retry_delay_ms(4), 160);
    }

    #[test]
    fn delay_saturates_at_max_delay() {
        let cfg = config(10, 25);
        assert_eq!(cfg.retry_delay_ms(0), 10);
        assert_eq!(cfg.retry_delay_ms(1), 20);
        assert_eq!(cfg.retry_delay_ms(2), 25);
        assert_eq!(cfg.retry_delay_ms(3), 25);
        assert_eq!(cfg.retry_delay_ms(100), 25);
    }

    #[test]
    fn huge_retry_index_does_not_overflow() {
        // Far beyond any safe exponent: must saturate, not panic.
        assert_eq!(config(2, 1000).retry_delay_ms(u32::MAX), 1000);
        assert_eq!(config(u64::MAX, 1000).retry_delay_ms(63), 1000);
    }

    #[test]
    fn max_delay_caps_even_the_first_retry() {
        assert_eq!(config(5000, 100).retry_delay_ms(0), 100);
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
///
/// Only transient errors are retried; permanent errors abort immediately.
/// `max_attempts` includes the first call, and delays grow exponentially
/// (`base_delay_ms * 2^n`) but saturate at `max_delay_ms` without overflow.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let mut attempts = 0u32;
    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(err) if !err.is_transient() => return Err(err),
            Err(err) => {
                if attempts >= config.max_attempts {
                    return Err(err);
                }
                sleeper.sleep_ms(config.retry_delay_ms(attempts - 1));
            }
        }
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` executes a job with a configurable bounded exponential retry
policy:

- only transient errors (`RetryError::Transient`) are retried; permanent
  errors (`RetryError::Permanent`) return immediately;
- `max_attempts` is the total number of attempts, including the first call;
- the delay before retry *n* (0-based) is
  `min(base_delay_ms * 2^n, max_delay_ms)`, computed with saturating
  arithmetic so it never overflows even for very large attempt counts;
- delays are injected through the `Sleeper` trait, so tests can use
  `FakeSleeper` to record every requested delay instead of actually waiting.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 3,
    base_delay_ms: 10,
    max_delay_ms: 1000,
};
let mut sleeper = FakeSleeper::default();

let result = run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("temporary".into()))
});

assert!(result.is_err());
assert_eq!(sleeper.sleeps, vec![10, 20]);
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn succeeds_on_first_attempt_without_sleeping() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(5, 10, 1000);

    let result = run_job(&cfg, &mut sleeper, || Ok(()));

    assert_eq!(result, Ok(()));
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn permanent_error_returns_immediately() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(5, 10, 1000);

    let result = run_job(&cfg, &mut sleeper, || {
        Err(RetryError::Permanent("bad input".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_error_is_retried_until_success() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(3, 10, 1000);
    let mut calls = 0;

    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("nope".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(3, 10, 1000);
    let mut calls = 0;

    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("always".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("always".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}

#[test]
fn single_attempt_config_never_waits() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(1, 10, 1000);
    let mut calls = 0;

    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("nope".into()))
    });

    assert!(result.is_err());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn delays_saturate_at_max_delay_ms() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(5, 10, 25);

    let result = run_job(&cfg, &mut sleeper, || {
        Err(RetryError::Transient("nope".into()))
    });

    assert!(result.is_err());
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn many_attempts_never_overflow_and_saturate() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(100, 2, 1000);

    let result = run_job(&cfg, &mut sleeper, || {
        Err(RetryError::Transient("nope".into()))
    });

    assert!(result.is_err());
    assert_eq!(sleeper.sleeps.len(), 99);
    assert!(sleeper.sleeps.iter().all(|&ms| ms <= 1000));
    assert_eq!(sleeper.sleeps[..6], [2, 4, 8, 16, 32, 64]);
    assert_eq!(sleeper.sleeps[9..], vec![1000; 90]);
}

#[test]
fn retries_stop_after_transient_then_permanent_error() {
    let mut sleeper = FakeSleeper::default();
    let cfg = config(10, 10, 1000);
    let mut calls = 0;

    let result = run_job(&cfg, &mut sleeper, || {
        calls += 1;
        if calls < 3 {
            Err(RetryError::Transient("flaky".into()))
        } else {
            Err(RetryError::Permanent("fatal".into()))
        }
    });

    assert_eq!(result, Err(RetryError::Permanent("fatal".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![10, 20]);
}
